def transform(grid):
    h, w = len(grid), len(grid[0])

    # Try diagonal stripes indexed by either diagonal coordinate.
    for keyfun in (lambda r, c: c-r, lambda r, c: r+c):
        known = {}
        valid = True
        for r in range(h):
            for c in range(w):
                v = grid[r][c]
                if v:
                    k = keyfun(r, c)
                    if k in known and known[k] != v:
                        valid = False
                        break
                    known[k] = v
            if not valid:
                break
        if valid and known:
            # Find a periodic assignment consistent with all observed stripes.
            lo = min(keyfun(r, c) for r in range(h) for c in range(w))
            hi = max(keyfun(r, c) for r in range(h) for c in range(w))
            for p in range(1, hi-lo+2):
                phases = {}
                ok = True
                for k, v in known.items():
                    q = k % p
                    if q in phases and phases[q] != v:
                        ok = False
                        break
                    phases[q] = v
                if ok and len(phases) == p:
                    return [[phases[keyfun(r,c) % p] for c in range(w)]
                            for r in range(h)]

    # For horizontal color bands, infer a repeating row sequence.
    rowclues = {r: row[0] for r, row in enumerate(grid)
                if all(x == row[0] for x in row) and row[0] != 0}
    if rowclues:
        h = len(grid)
        for p in range(1, h+1):
            vals = {}
            ok = True
            for r,v in rowclues.items():
                q = r % p
                if q in vals and vals[q] != v:
                    ok = False
                    break
                vals[q] = v
            if ok:
                # Fill unobserved phases by nearest known phase.
                for q in range(p):
                    if q not in vals:
                        near = min(vals, key=lambda x: min((q-x)%p, (x-q)%p))
                        vals[q] = vals[near]
                return [[vals[r%p]] * len(grid[0]) for r in range(h)]

    return [row[:] for row in grid]
